#!/usr/bin/env python3
"""Serialize the checked bibliography; reuse cumulative keys verbatim."""
from pathlib import Path
import re, json
OUT=Path(__file__).resolve().parent
WORK=OUT.parents[1]
entries={}
def add(key,kind,**fields):
    fields.setdefault('note','verified')
    entries[key]=(kind,fields)

