entries['bruzzorubtsov2012localization'][1].update(volume='10',number='4',pages='1442--1454')
cumulative=(WORK/'references_cumulative.bib').read_text()
reuse={}
for m in re.finditer(r'(?m)^@\w+\{([^,\s]+),',cumulative):
    pos=m.start(); i=cumulative.find('{',pos); depth=0
    for j in range(i,len(cumulative)):
        if cumulative[j]=='{': depth+=1
        elif cumulative[j]=='}':
            depth-=1
            if depth==0:
                reuse[m.group(1)]=cumulative[pos:j+1]; break
needed=sorted({k for item in json.loads((OUT/'items.json').read_text()) for k in item['refs']})
missing=[k for k in needed if k not in entries and k not in reuse]
assert not missing, missing
chunks=[]
for key in needed:
    if key in reuse:
        chunks.append(reuse[key]); print('Reused cumulative:',key); continue
    kind,fields=entries[key]
    chunks.append('@'+kind+'{'+key+',\n'+',\n'.join('  '+k+' = {'+str(v)+'}' for k,v in fields.items())+'\n}')
(OUT/'references.bib').write_text('\n\n'.join(chunks)+'\n')
print('Wrote',len(chunks),'entries, including',sum('note = {unverified}' in c for c in chunks),'unverified lead(s).')
